        if($op==='archive'){$workflowId=(string)($_POST['workflow_id']??'');research_publication_archive($pdo,$u,$workflowId);$success='Publication workflow archived.';}
        if($op==='thread_create'){$workflowId=(string)($_POST['workflow_id']??'');research_publication_thread_create($pdo,$u,$workflowId,['title'=>(string)($_POST['title']??''),'body'=>(string)($_POST['body']??''),'anchor_type'=>(string)($_POST['anchor_type']??'general'),'anchor_public_id'=>(string)($_POST['anchor_public_id']??''),'locator'=>['label'=>(string)($_POST['locator_label']??'')]]);$success='Review thread added.';}
