<aside class="publicationCenterRail"><?php if($workflow):?><div class="card"><h3>Review rounds</h3><?php if(!$workflow['rounds']):?><p class="meta">No review rounds yet.</p><?php endif?><?php foreach($workflow['rounds'] as $round):?><p><a href="/research-reviews.php?id=<?=h((string)$round['review_public_id'])?>">Round <?=h((string)$round['round_number'])?></a><br><span class="meta">Document rev <?=h((string)$round['document_revision_number'])?> · <?=h((string)$round['created_at'])?></span></p><?php endforeach?></div><?php else:?><div class="card"><h3>Publishing rules</h3><p class="meta">Reviewer votes never publish content by themselves. The workflow must satisfy every configured gate, remain pinned to the reviewed document revision, and an authorized publisher must explicitly publish it.</p><p><a href="/research-reviews.php">Open Review Center</a></p></div><?php endif?></aside>
